#!/bin/bash
python3 -c $'import sys,json\nR=json.loads(sys.argv[1]) if len(sys.argv)>1 else {\'0,*\':[0,\'=\',1]}\nm=json.dumps(R,sort_keys=True,separators=(\',\',\':\'))\ns=m\nq=h=0;t={i:c for i,c in enumerate(s) if c!=\'_\'};hist=[]\nwhile True:\n hist.append([q,h,sorted(t.items())]);c=t.get(h,\'_\');v=R.get(str(q)+\',\'+c) or (R.get(str(q)+\',*\') if c!=\'_\' else None)\n if v is None:break\n q,w,d=v\n if w==\'=\':w=c\n if w==\'_\':t.pop(h,None)\n else:t[h]=w\n h+=d\nb=json.dumps([R,s,hist],sort_keys=True,separators=(\',\',\':\')).encode()\ndef G(b):\n n=1\n for v in b:n=n*257+v+1\n return n\ndef D(n):\n a=[]\n while n>1:\n  n,r=divmod(n,257);assert r;a.append(r-1)\n return bytes(a[::-1])\na=G(b);assert D(a)==b\nimport hashlib\ndigest=hashlib.sha256(b).digest();b=digest;a=G(b);assert D(a)==b\np=[];k=2;g=1\nwhile len(p)<len(b):\n if all(k%d for d in p if d*d<=k):p.append(k)\n k+=1\nfor d,v in zip(p,b):g*=d**(v+1)\nz=g;back=[]\nfor d in p:\n e=0\n while z%d==0:z//=d;e+=1\n assert 1<=e<=256\n back.append(e-1)\nassert z==1 and bytes(back)==b\nphase=(-1)**((bin(a).count(\'1\')+bin(g).count(\'1\'))%2)\nprint(json.dumps(dict(steps=len(hist)-1,halted=True,self_input=s==m,read_all=h==len(s),description_bits=G(m.encode()).bit_length(),base257_bits=a.bit_length(),prime_bits=g.bit_length(),history_sha256=digest.hex(),dual_roundtrip=True,H_phase_H=[(1+phase)/2,(1-phase)/2],final=hist[-1])))\n' "$@"
